#[cfg(unix)]
fn parse_signal(spec: &str) -> Option<Signal> {
    if spec.is_empty() {
        return None;
    }
    // a signal number like "13"
    if spec.bytes().all(|b| b.is_ascii_digit()) {
        // signal 0 ("EXIT") is rejected
        return spec
            .parse::<i32>()
            .ok()
            .and_then(|num| Signal::try_from(num).ok());
    }
    // a signal name like "PIPE", "SIGPIPE", "pipe" or "SigPipe"
    let upper = spec.to_uppercase();
    let name = upper.strip_prefix("SIG").unwrap_or(&upper);
    Signal::from_str(&format!("SIG{name}")).ok()
}

#[cfg(unix)]
fn parse_ignore_signals(spec: &OsStr) -> UResult<Vec<Signal>> {
    let mut signals = Vec::new();
    for part in spec.to_string_lossy().split(',') {
        if part.is_empty() {
            // an empty signal is a no-op
            continue;
        }
        let sig = parse_signal(part).ok_or_else(|| {
            USimpleError::new(125, format!("{}: invalid signal", part.quote()))
        })?;
        if !signals.contains(&sig) {
            signals.push(sig);
        }
    }
    Ok(signals)
}

#[cfg(unix)]
fn all_signals() -> Vec<Signal> {
    (1..=64).filter_map(|i| Signal::try_from(i).ok()).collect()
}

fn make_options(matches: &clap::ArgMatches) -> UResult<Options<'_>> {
    let ignore_env = matches.get_flag("ignore-environment");
    let line_ending = LineEnding::from_zero_flag(matches.get_flag("null"));
    let running_directory = matches.get_one::<OsString>("chdir").map(|s| s.as_os_str());
    let files = match matches.get_many::<OsString>("file") {
        Some(v) => v.map(|s| s.as_os_str()).collect(),
        None => Vec::with_capacity(0),
    };
    let unsets = match matches.get_many::<OsString>("unset") {
        Some(v) => v.map(|s| s.as_os_str()).collect(),
        None => Vec::with_capacity(0),
    };
    let argv0 = matches.get_one::<OsString>("argv0").map(|s| s.as_os_str());

    #[cfg(unix)]
    let (ignore_signals, ignore_all_signals) = if matches.value_source("ignore-signal")
        == Some(clap::builder::ValueSource::CommandLine)
    {
        // "Without SIG, all known signals are included" - sigaction(2)
        // errors are ignored in that case, as some signals (e.g., SIGKILL,
        // SIGSTOP) cannot be ignored.
        match matches.get_one::<OsString>("ignore-signal") {
            Some(spec) => (parse_ignore_signals(spec)?, false),
            None => (Vec::new(), true),
        }
    } else {
        (Vec::new(), false)
    };

    let mut opts = Options {
        ignore_env,
        line_ending,
        running_directory,
        files,
        unsets,
        sets: vec![],
        program: vec![],
        argv0,
        #[cfg(unix)]
        ignore_signals,
        #[cfg(unix)]
        ignore_all_signals,
    };

